  q("closeDetail").onclick=function(){hide(q("detailOverlay"))};q("evaluateBtn").onclick=evaluate;q("improveBtn").onclick=improve;q("saveSchemeBtn").onclick=saveScheme;q("exportJsonBtn").onclick=exportJson;q("exportCsvBtn").onclick=exportCsv;q("savedBtn").onclick=openSaved;q("closeSaved").onclick=function(){hide(q("savedOverlay"))};q("fontBtn").onclick=function(){show(q("fontOverlay"))};q("closeFont").onclick=function(){hide(q("fontOverlay"))};q("fontRange").oninput=function(){setFont(this.value)};Array.prototype.forEach.call(document.querySelectorAll("[data-scale]"),function(b){b.onclick=function(){setFont(b.dataset.scale)}});q("resetFont").onclick=function(){setFont(115)};q("logoutBtn").onclick=logout;
